[hidden] { display: none !important; }

:root {
  color-scheme: light;
  font-family: system-ui, sans-serif;
  color: #19324a;
  background: #dff5eb;
  font-size: 16px;
}

* { box-sizing: border-box; }
body {
  min-height: 100vh;
  margin: 0;
  padding: 24px;
  display: grid;
  place-items: center;
  background-color: #dff5eb;
  background-image: radial-gradient(#b8e5d1 1.5px, transparent 1.5px);
  background-size: 22px 22px;
}
.board {
  width: min(100%, 480px);
  padding: clamp(24px, 7vw, 42px);
  border: 4px solid #19324a;
  border-radius: 18px;
  background: #fffdf5;
  box-shadow: 9px 9px 0 #19324a;
  text-align: center;
}
.eyebrow { margin: 0 0 8px; color: #347b66; font-weight: 800; letter-spacing: .14em; font-size: .85rem; }
h1 { margin: 0; font-size: clamp(2.4rem, 10vw, 3.5rem); line-height: 1; }
.subtitle { margin: 14px 0 28px; color: #52697b; }
.progress { margin: 0 0 18px; color: #52697b; font-weight: 700; }
.tiles { min-height: 82px; display: flex; justify-content: center; align-items: center; gap: 8px; margin-bottom: 26px; }
.tile {
  width: 48px; height: 56px; display: grid; place-items: center;
  border: 3px solid #19324a; border-radius: 8px; background: #f4c95d;
  box-shadow: 3px 3px 0 #19324a; font-size: 1.65rem; font-weight: 850;
}
label { display: block; margin-bottom: 8px; text-align: left; font-weight: 750; }
input {
  width: 100%; min-height: 52px; padding: 10px 14px; border: 3px solid #19324a;
  border-radius: 9px; background: white; color: #19324a; font: inherit; font-size: 1.15rem;
}
input:focus-visible, button:focus-visible { outline: 4px solid #55a989; outline-offset: 3px; }
.feedback { min-height: 28px; margin: 10px 0 12px; font-weight: 750; }
.feedback.correct { color: #267653; }
.feedback.wrong { color: #a44338; }
.actions { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
button {
  min-height: 50px; padding: 10px 18px; border: 3px solid #19324a; border-radius: 9px;
  background: #347b66; color: white; font: inherit; font-weight: 800; cursor: pointer;
  box-shadow: 3px 3px 0 #19324a; transition: transform .12s, box-shadow .12s, background .12s;
}
button:hover:not(:disabled) { background: #28654f; }
button:active:not(:disabled) { transform: translate(2px, 2px); box-shadow: 1px 1px 0 #19324a; }
button.secondary { background: #f4c95d; color: #19324a; }
button.secondary:hover:not(:disabled) { background: #e9b83f; }
button:disabled { opacity: .5; cursor: not-allowed; }
#result h2 { margin: 4px 0 8px; font-size: 2rem; }
.trophy { color: #e5ad2d; font-size: 4rem; line-height: 1.2; }
.score-line { margin: 18px 0 0; color: #52697b; font-weight: 700; }
.final-score { margin: 4px 0 24px; font-size: 2.5rem; font-weight: 900; }
#restart { min-width: 180px; }
@media (max-width: 390px) {
  body { padding: 16px; }
  .tile { width: 40px; height: 50px; font-size: 1.4rem; }
  .tiles { gap: 6px; }
}

const words = ['planet', 'garden', 'puzzle', 'kitten', 'orange', 'rocket'];
const game = document.querySelector('#game');
const result = document.querySelector('#result');
const tiles = document.querySelector('#tiles');
const progress = document.querySelector('#progress');
const form = document.querySelector('#answer-form');
const answer = document.querySelector('#answer');
const feedback = document.querySelector('#feedback');
const check = document.querySelector('#check');
const next = document.querySelector('#next');
let index = 0;
let score = 0;
let checked = false;

function scramble(word) {
  const letters = word.split('');
  for (let i = letters.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [letters[i], letters[j]] = [letters[j], letters[i]];
  }
  if (letters.join('') === word) letters.push(letters.shift());
  return letters;
}

function showWord() {
  progress.textContent = `Word ${index + 1} of ${words.length}`;
  tiles.replaceChildren(...scramble(words[index]).map((letter) => {
    const tile = document.createElement('span');
    tile.className = 'tile';
    tile.textContent = letter.toUpperCase();
    return tile;
  }));
  answer.value = '';
  answer.disabled = false;
  check.disabled = false;
  checked = false;
  next.disabled = true;
  feedback.textContent = '';
  feedback.className = 'feedback';
  answer.focus();
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  if (checked || !answer.value.trim()) return;
  checked = true;
  const correct = answer.value.trim().toLowerCase() === words[index];
  if (correct) {
    score++;
    feedback.textContent = 'Correct! Nice spelling.';
    feedback.classList.add('correct');
  } else {
    feedback.textContent = `Not quite. The word was ${words[index]}.`;
    feedback.classList.add('wrong');
  }
  answer.disabled = true;
  check.disabled = true;
  next.disabled = false;
  next.focus();
});

next.addEventListener('click', () => {
  if (!checked) return;
  index++;
  if (index === words.length) {
    game.hidden = true;
    result.hidden = false;
    document.querySelector('#final-score').textContent = `${score} / ${words.length}`;
    document.querySelector('#restart').focus();
  } else {
    showWord();
  }
});

document.querySelector('#restart').addEventListener('click', () => {
  index = 0;
  score = 0;
  game.hidden = false;
  result.hidden = true;
  showWord();
});

showWord();
